param()
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$qpf=[double][Diagnostics.Stopwatch]::Frequency
$eventNames=@('CPU_CLK_UNHALTED.THREAD','CPU_CLK_UNHALTED.REF_TSC','L2_RQSTS.DEMAND_DATA_RD_MISS','L2_RQSTS.ALL_DEMAND_DATA_RD','OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD','OFFCORE_REQUESTS.DEMAND_DATA_RD')
function ParseNum([string]$s){$s=$s.Trim();if($s -notmatch '^\d[\d,]*(?:\.\d+)?$'){return [double]::NaN};return [double]::Parse($s.Replace(',',''),[Globalization.CultureInfo]::InvariantCulture)}
function Finite([double]$n){return -not [double]::IsNaN($n) -and -not [double]::IsInfinity($n)}
function UnionCoverage([double]$a,[double]$b,[object[]]$windows,[double]$u){
 $segs=[Collections.Generic.List[object]]::new();foreach($w in $windows){$s=[math]::Max($a,[double]$w.s+$u);$e=[math]::Min($b,[double]$w.e-$u);if($e -gt $s){$segs.Add([pscustomobject]@{s=$s;e=$e})}}
 $sorted=@($segs|Sort-Object s,e);$un=[Collections.Generic.List[object]]::new();foreach($x in $sorted){if(!$un.Count -or $x.s -gt $un[$un.Count-1].e){$un.Add([pscustomobject]@{s=$x.s;e=$x.e})}else{$un[$un.Count-1].e=[math]::Max($un[$un.Count-1].e,$x.e)}}
 $covered=0.;$gap=0.;$cursor=$a;foreach($x in $un){$gap=[math]::Max($gap,[double]$x.s-$cursor);$covered+=[double]$x.e-[double]$x.s;$cursor=[double]$x.e};$gap=[math]::Max($gap,$b-$cursor);return [pscustomobject]@{coverage=$covered/($b-$a);gap=$gap}
}
function Gate($r){
 $have=@($r.channel_names -split ',');foreach($required in @($r.required_channels -split ',')){if($have -notcontains $required){return 'HOLD'}};if(!$r.channels_present -or $r.LP -ne $r.expected_LP -or $r.window_ids -ne $r.expected_window_ids -or !$r.temporal_pass -or !$r.ratio_pass){return 'HOLD'}
 foreach($n in @($r.D2,$r.M2,$r.M3)){if(!(Finite ([double]$n)) -or [double]$n -lt 0){return 'HOLD'}}
 if($r.D2 -lt 10000){return 'NOT_ESTIMABLE+HOLD'}
 if($r.M2 -gt $r.D2){return 'FAIL'}
 if($r.H2 -gt .10 -or $r.H32 -gt .10){return 'FAIL'}
 return 'PASS'
}
$all=[Collections.Generic.List[object]]::new();$runMeta=[Collections.Generic.List[object]]::new()
foreach($cap in @('capture_d8_r4','capture_d8_revalidation_r4')){
 $dir=Join-Path $root $cap;$raw=Get-Content -Raw (Join-Path $dir 'emon_stdout.txt');$map=@(Import-Csv (Join-Path $dir 'clock_map.csv'));$marks=@(Import-Csv (Join-Path $dir 'eviction_windows.csv'));$stdout=Get-Content -Raw (Join-Path $dir 'harness.stdout.txt')
 $ftscMatch=[regex]::Match($stdout,'(?m)^FTSC_QPC_HZ=([0-9.]+)');$qpcMatch=[regex]::Match($stdout,'(?m)^QPC_FREQ_HZ=(\d+)');$emonMatch=[regex]::Match($raw,'(?m)^TSC Freq\s+\.{2,}\s+([0-9.]+) MHz')
 if(!$ftscMatch.Success -or !$qpcMatch.Success -or !$emonMatch.Success){throw "missing qualified f_TSC/QPC in $cap"};$ftsc=[double]$ftscMatch.Groups[1].Value;$qpcRecorded=[double]$qpcMatch.Groups[1].Value;$emonTsc=[double]$emonMatch.Groups[1].Value*1e6;$ftscOk=($ftsc -gt 0 -and $qpcRecorded -eq $qpf -and [math]::Abs($ftsc-$emonTsc)/$emonTsc -le .001)
 $x=[Collections.Generic.List[double]]::new();$y=[Collections.Generic.List[double]]::new();$br=[Collections.Generic.List[double]]::new();$x0=[double]::NaN;$y0=[double]::NaN;foreach($m in $map){if([string]$m.sample -match '^MAP\d+$'){$xf=[double]$m.filetime_100ns/10000000.0;$ymid=([double]$m.qpc_pre+[double]$m.qpc_post)/2;if($x.Count -eq 0){$x0=$xf;$y0=$ymid};$x.Add($xf-$x0);$y.Add($ymid-$y0);$br.Add(([double]$m.qpc_post-[double]$m.qpc_pre)/$qpf)}}
 if($x.Count -lt 20){throw "clock map <20: $cap"};$xm=($x|Measure-Object -Average).Average;$ym=($y|Measure-Object -Average).Average;$num=0.;$den=0.;for($i=0;$i-lt$x.Count;$i++){$num+=($x[$i]-$xm)*($y[$i]-$ym);$den+=($x[$i]-$xm)*($x[$i]-$xm)};if($den -le 0){throw 'singular clock map'};$slope=$num/$den;$inter=$ym-$slope*$xm;$res=[Collections.Generic.List[double]]::new();for($i=0;$i-lt$x.Count;$i++){$res.Add([math]::Abs($y[$i]-($inter+$slope*$x[$i]))/$qpf)};$u=($res|Measure-Object -Maximum).Maximum+($br|Measure-Object -Maximum).Maximum/2+.0005
 $records=[Collections.Generic.List[object]]::new();foreach($chunk in [regex]::Split($raw,'(?m)^==========\s*$')){$tm=[regex]::Match($chunk,'(?m)^(\d{1,2}/\d{1,2}/\d{4}\s+\d{2}:\d{2}:\d{2}\.\d{3})\s*$');if(!$tm.Success){continue};$dt=[datetime]::ParseExact($tm.Groups[1].Value,'M/d/yyyy HH:mm:ss.fff',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeLocal);$end=($y0+$inter+$slope*(([double]$dt.ToFileTimeUtc()/10000000.0)-$x0))/$qpf;$ev=@{};foreach($line in ($chunk -split "`r?`n")){if(!$line.Contains("`t")){continue};$f=$line -split "`t";$name=$f[0].Trim();if($eventNames -contains $name){$vals=[Collections.Generic.List[double]]::new();for($j=1;$j-lt$f.Count;$j++){$vals.Add((ParseNum $f[$j]))};$ev[$name]=$vals.ToArray()}};if(@($eventNames|Where-Object {!$ev.ContainsKey($_)}).Count){continue};$duration=$ev['CPU_CLK_UNHALTED.REF_TSC'][0]/$ftsc;if(!(Finite $duration) -or $duration -le 0 -or $duration -gt .100){continue};$records.Add([pscustomobject]@{group_id=$records.Count;s=$end-$duration;e=$end;duration=$duration;ev=$ev})}
 if($records.Count -lt 20){throw "EMON groups <20 after common acquisition-duration parse: $cap count=$($records.Count)"}
 $markBy=@{};foreach($m in $marks){$k="$([int]$m.Pcore)/$($m.condition)";if($markBy.ContainsKey($k)){throw "duplicate mark $k"};$markBy[$k]=$m}
 $summaries=@{};foreach($line in ($stdout -split "`r?`n")){if($line -match '^CACHE_LATENCY Pcore=(\d+) LP=(\d+) condition=(\S+) samples=(\d+) median_cycles=(\d+) p95_cycles=(\d+)'){$summaries["$($Matches[1])/$($Matches[3])"]=[pscustomobject]@{samples=[int]$Matches[4];median=[double]$Matches[5]}}}
 for($core=0;$core-lt 8;$core++){foreach($cond in @('cold_shards8','hot_shards8')){$key="$core/$cond";$mark=$markBy[$key];$otherCond=if($cond -eq 'hot_shards8'){'cold_shards8'}else{'hot_shards8'};$otherMark=$markBy["$core/$otherCond"];$a=[double]$mark.qpc_start/$qpf;$b=[double]$mark.qpc_end/$qpf;$padA=[double]$mark.qpc_pad_start/$qpf;$padB=[double]$mark.qpc_pad_end/$qpf;$usable=[Collections.Generic.List[object]]::new();foreach($rec in $records){$cross=$false;if($otherMark){$oa=[double]$otherMark.qpc_start/$qpf;$ob=[double]$otherMark.qpc_end/$qpf;$opa=[double]$otherMark.qpc_pad_start/$qpf;$opb=[double]$otherMark.qpc_pad_end/$qpf;$cross=(($rec.s-$u -lt $ob -and $rec.e+$u -gt $oa)-or($rec.s-$u -ge $opa -and $rec.e+$u -le $opb))};if(!$cross -and $rec.s -lt $b -and $rec.e -gt $a -and $rec.s-$u -ge $padA -and $rec.e+$u -le $padB){$usable.Add($rec)}};$cov=UnionCoverage $a $b @($usable|%{[pscustomobject]@{s=$_.s;e=$_.e}}) $u;$maxwin=0.;if($usable.Count){$maxwin=($usable|Measure-Object duration -Maximum).Maximum};$margin1=($a-$padA)/$qpf*$qpf;$margin2=$padB-$b
 $worker=2*$core;$sib=$worker+1;$D2=0.;$M2=0.;$M3=0.;$OffD=0.;$OffM=0.;$sD2=0.;$sM2=0.;$sM3=0.;$validChannels=$true;$sameIds=$true
 foreach($rec in $usable){foreach($nm in @('L2_RQSTS.ALL_DEMAND_DATA_RD','L2_RQSTS.DEMAND_DATA_RD_MISS','OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD','OFFCORE_REQUESTS.DEMAND_DATA_RD')){$vals=$rec.ev[$nm];if($vals.Count -le ($worker+1) -or !(Finite $vals[$worker+1]) -or $vals[$worker+1] -lt 0){$validChannels=$false}};$D2+=$rec.ev['L2_RQSTS.ALL_DEMAND_DATA_RD'][$worker+1];$M2+=$rec.ev['L2_RQSTS.DEMAND_DATA_RD_MISS'][$worker+1];$M3+=$rec.ev['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'][$worker+1];$OffD+=$rec.ev['OFFCORE_REQUESTS.DEMAND_DATA_RD'][$worker+1];$OffM+=$rec.ev['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'][$worker+1];$sD2+=$rec.ev['L2_RQSTS.ALL_DEMAND_DATA_RD'][$sib+1];$sM2+=$rec.ev['L2_RQSTS.DEMAND_DATA_RD_MISS'][$sib+1];$sM3+=$rec.ev['OFFCORE_REQUESTS.L3_MISS_DEMAND_DATA_RD'][$sib+1]}
 $h2=if($D2 -gt 0){$M2/$D2}else{[double]::NaN};$h32=if($D2 -gt 0){$M3/$D2}else{[double]::NaN};$old=if($OffD -gt 0){$OffM/$OffD}else{[double]::NaN};$temporal=($ftscOk -and ($a-$padA) -ge .200 -and ($padB-$b) -ge .200 -and $usable.Count -ge 20 -and $cov.coverage -ge .95 -and $cov.gap -le .020 -and $maxwin -le .100 -and $u -le .001 -and ($b-$a) -ge 2.0);$ratio=[double]::NaN;$ratioPass=$false;$cold=$summaries["$core/cold_shards8"];$hot=$summaries["$core/hot_shards8"];if($cold -and $hot -and $hot.median -gt 0){$ratio=$cold.median/$hot.median;$ratioPass=($ratio -ge 1.50 -and $cold.samples -ge 20 -and $hot.samples -ge 20)}
 $windowIds=(@($usable|ForEach-Object {$_.group_id}) -join ',');$channelList=($eventNames -join ',');$r=[pscustomobject]@{run=if($cap -eq 'capture_d8_r4'){'Q'}else{'R'};P=$core;LP=$worker;expected_LP=$worker;window_ids=$windowIds;expected_window_ids=$windowIds;channel_names=$channelList;required_channels=$channelList;condition=if($cond -eq 'hot_shards8'){'hot'}else{'cold'};windows=$usable.Count;D2=[double]$D2;M2=[double]$M2;M3=[double]$M3;SMT_D2=[double]$sD2;SMT_M2=[double]$sM2;SMT_M3=[double]$sM3;H2=[double]$h2;H32=[double]$h32;D_offcore=[double]$OffD;M3_over_Doff=[double]$old;coverage_pct=100*$cov.coverage;gap_ms=1000*$cov.gap;max_window_ms=1000*$maxwin;u_ms=1000*$u;ratio=$ratio;ratio_pass=$ratioPass;channels_present=$validChannels;temporal_pass=$temporal;status=''};$r.status=if($cond -eq 'hot_shards8'){Gate $r}else{if($temporal -and $validChannels -and $old -ge .90 -and $ratioPass){'PASS'}else{'HOLD'}};$all.Add($r)
 }}
 $runMeta.Add([pscustomobject]@{run=if($cap -eq 'capture_d8_r4'){'Q'}else{'R'};ftsc_MHz=$ftsc/1e6;emon_tsc_MHz=$emonTsc/1e6;ftsc_qualified=$ftscOk;groups=$records.Count;u_ms=1000*$u})
}
foreach($run in @('Q','R')){$rows=@($all|Where-Object {$_.run -eq $run});$rows|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $root "D8_DERIVED_${run}_r6.csv")}
$all|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $root 'D8_DERIVED_QR_r6.csv')
$negative=[Collections.Generic.List[object]]::new();$baseHot=$all|Where-Object {$_.run -eq 'Q' -and $_.P -eq 0 -and $_.condition -eq 'hot'}|Select-Object -First 1
foreach($case in @('H2_GT_0.10','H3_GT_0.10','D2_LT_10000','CHANNEL_MISSING','MIXED_LP','MIXED_WINDOWS')){$m=$baseHot.PSObject.Copy();$m.temporal_pass=$true;$m.ratio_pass=$true;$m.D2=[double]$baseHot.D2;$m.M2=[double]$baseHot.M2;$m.M3=[double]$baseHot.M3;$m.H2=[double]$baseHot.H2;$m.H32=[double]$baseHot.H32;switch($case){'H2_GT_0.10'{$m.H2=.100001};'H3_GT_0.10'{$m.H32=.100001};'D2_LT_10000'{$m.D2=9999};'CHANNEL_MISSING'{$m.channel_names=($m.channel_names -replace 'L2_RQSTS.ALL_DEMAND_DATA_RD,?','')};'MIXED_LP'{$m.LP=$m.LP+1};'MIXED_WINDOWS'{$ids=@($m.window_ids -split ',');$m.window_ids=($ids|Select-Object -Skip 1) -join ','}};$negative.Add([pscustomobject]@{test=$case;mutated_field=$case;result=(Gate $m);expected=switch($case){'H2_GT_0.10'{'FAIL'};'H3_GT_0.10'{'FAIL'};'D2_LT_10000'{'NOT_ESTIMABLE+HOLD'};'CHANNEL_MISSING'{'HOLD'};'MIXED_LP'{'HOLD'};'MIXED_WINDOWS'{'HOLD'}}})}
$cores=@($all|Where-Object {$_.run -eq 'Q' -and $_.condition -eq 'hot'}|ForEach-Object {$_.PSObject.Copy()}|Sort-Object P);$cores[7].H2=.100001;$mean=($cores|Measure-Object H2 -Average).Average;$failed=@($cores|Where-Object {$_.H2 -gt .10}).Count -gt 0;$negative.Add([pscustomobject]@{test='CORE_FAIL_HIDDEN_BY_MEAN';mutated_field='P7.H2';mean_H2=$mean;failed_cores=@($cores|Where-Object {$_.H2 -gt .10}).Count;result=if($failed){'FAIL'}else{'PASS'};expected='FAIL'})
$negative|Select-Object test,mutated_field,mean_H2,failed_cores,result,expected|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $root 'D8_NEGATIVE_TESTS_r6.csv')
$runMeta|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $root 'D8_TEMPORAL_QR_r6.csv')
$runMeta|Format-Table -AutoSize|Out-String|Write-Output;$all|Where-Object {$_.condition -eq 'hot'}|Select-Object run,P,LP,windows,H2,H32,D2,coverage_pct,gap_ms,status|Format-Table -AutoSize|Out-String -Width 240|Write-Output;$negative|Format-Table -AutoSize|Out-String -Width 200|Write-Output



